    sep_cols = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]

    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]

    colors = [grid[r][c] for r in range(h) for c in range(w) if grid[r][c] != sep]
    background = max(set(colors), key=colors.count)

    result = []
    for ri in range(len(row_edges) - 1):
        out_row = []
        for ci in range(len(col_edges) - 1):
            cells = [
                grid[r][c]
                for r in range(row_edges[ri] + 1, row_edges[ri + 1])
                for c in range(col_edges[ci] + 1, col_edges[ci + 1])
            ]
            out_row.append(1 if sum(x != background for x in cells) >= 2 else background)
        result.append(out_row)
    return result
